import{c as t,Q as e,j as i,m as l}from"./chunks/framework.DOi4mjdC.js";const s="/assets/%E7%BA%BF%E7%A8%8B%E7%BB%93%E6%9E%84%E7%A4%BA%E6%84%8F%E5%9B%BE.Buixegfr.png",d="/assets/UB%E5%86%85%E5%AD%98%E5%88%86%E9%85%8D.CycysjF4.png",g=JSON.parse('{"title":"编程模型","description":"","frontmatter":{},"headers":[{"level":1,"title":"编程模型","slug":"编程模型"},{"level":2,"title":"适用场景","slug":"适用场景"},{"level":2,"title":"线程架构","slug":"线程架构"},{"level":2,"title":"Warp执行机制","slug":"warp执行机制"},{"level":2,"title":"UB划分","slug":"ub划分"},{"level":2,"title":"内存空间说明","slug":"内存空间说明"}],"relativePath":"api/SIMT-API/SIMT编程简介/编程模型.md","filePath":"api/SIMT-API/SIMT编程简介/编程模型.md"}'),p={name:"api/SIMT-API/SIMT编程简介/编程模型.md"};function r(n,a,o,c,h,u){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="编程模型" tabindex="-1">编程模型 <a class="header-anchor" href="#编程模型" aria-label="Permalink to &quot;编程模型&quot;">​</a></h1><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>SIMT编程适合控制流复杂和访存模式不规则的算子场景。由于每个线程拥有独立的控制流和地址计算能力，SIMT能够自然地处理条件分支逻辑，随机访问内存而无需受限于连续访存模式。同时，SIMT提供原子操作和线程间内存屏障等机制，支撑多线程对同一片内存的安全并发访问，适用于哈希表等需要冲突解决与数据同步的数据结构操作。SIMT的优势在于以线程为最小调度单元赋予每条执行路径充分的独立性，从而在制流复杂和访存模式不规则的场景下能够获得更高的开发效率与执行性能。</p><h2 id="线程架构" tabindex="-1">线程架构 <a class="header-anchor" href="#线程架构" aria-label="Permalink to &quot;线程架构&quot;">​</a></h2><p>SIMT编程模型采用分层的抽象线程组织结构，示意图如下所示，从顶层到底层依次为：Grid（线程块网格）、Thread Block（线程块）、Warp（线程束）和Thread（线程）。这种层次化的设计使得开发者可以方便地将并行计算问题映射到硬件资源上。</p><p><strong>图 1</strong> 线程结构示意图<br><img src="'+s+`" alt="" title="线程结构示意图"></p><p><strong>Thread（线程）</strong></p><p>线程是整个结构中的最小单元，每个线程独立完成计算任务，拥有独立的寄存器和栈空间。</p><p><strong>Thread Block（线程块）</strong></p><p>Thread Block是Grid的组成单元，由若干线程组成（最大2048个线程）。使用内置变量<a href="./扩展语法/内置变量.html#li076017381191">blockDim</a>来表示一个Thread Block启用的线程数量。在SIMT编程场景中，Thread Block有以下特点：</p><ul><li>同一Thread Block内的线程可以访问共享内存（UB）实现数据交互；Thread Block内的线程可通过同步机制实现协作；</li><li>在SIMT函数定义时可使用<a href="./扩展语法/核函数配置.html#section10465124215151">__launch_bounds__()</a>配置最大线程数。</li></ul><p><strong>Grid（线程块网格）</strong></p><p>Grid是SIMT线程层次结构的最顶层，由多个Thread Block组成。使用内置变量<a href="./扩展语法/内置变量.html#li20760123812911">gridDim</a>来表示Grid中启用的线程块数量。在SIMT编程场景，Grid有以下特征：</p><ul><li>Grid的维度配置由用户设置启动的AIV核数决定，核函数执行期间不可更改；</li><li>Grid中的所有线程块具有相同的尺寸和维度配置；</li><li>同一Grid中的线程块相互独立，按任意顺序执行；</li></ul><p>限制说明如下：</p><ul><li>Grid中线程块总数不能超过65535。</li></ul><p><strong>线程索引</strong></p><p>每个线程都有唯一的标识，开发者可以通过内置变量获取线程的信息，从而确定每个线程负责处理的数据，相关内置变量如下表所示：</p><table tabindex="0"><thead><tr><th>内置变量</th><th>说明</th><th>数据类型</th><th>约束</th></tr></thead><tbody><tr><td>gridDim</td><td>Grid的维度大小</td><td>dim3</td><td>gridDim.x * gridDim.y * gridDim.z&lt;= 65535；</td></tr><tr><td>blockDim</td><td>Thread Block的维度大小</td><td>dim3</td><td>blockDim.x * blockDim.y *blockDim.z &lt;= 2048</td></tr><tr><td>blockIdx</td><td>当前Thread Block在Grid中的索引</td><td>dim3</td><td>无</td></tr><tr><td>threadIdx</td><td>当前线程在Thread Block内的索引</td><td>dim3</td><td>无</td></tr></tbody></table><p>各Thread Block可通过线程块索引blockIdx进行标识，各线程可通过线程块内线程索引threadIdx进行标识。对于一维Grid和Block，索引计算公式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int idx = blockIdx.x * blockDim.x + threadIdx.x;</span></span></code></pre></div><p>对于二维Grid和Block，索引计算公式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x_index = blockIdx.x * blockDim.x + threadIdx.x;</span></span>
<span class="line"><span>int y_index = blockIdx.y * blockDim.y + threadIdx.y;</span></span></code></pre></div><h2 id="warp执行机制" tabindex="-1">Warp执行机制 <a class="header-anchor" href="#warp执行机制" aria-label="Permalink to &quot;Warp执行机制&quot;">​</a></h2><p>Warp是SIMT架构中基本的调度和执行单位。每个Warp包含32个线程，这些线程从相同的程序地址开始执行，拥有各自的指令地址计数器和寄存器状态，并且可以选择分支独立执行。在一个Thread Block内，所有线程按线性顺序被硬件自动划分为每32个线程一组的Warp，同一Warp内的所有线程执行同一条指令。</p><p>Warp内的线程虽然执行同一段代码，但可通过条件分支进入不同的执行路径，这种情况称为分支发散（Warp Divergence）。当Warp中的32个线程均执行相同的代码分支时，硬件利用率最高；一旦发生分支发散，硬件会串行执行每个分支路径，只有进入当前分支的线程（即活跃线程）会被执行，其余线程则被屏蔽，从而导致Warp执行效率下降。此外，同一Warp内的线程相互独立，彼此不能存在依赖关系。</p><p>Thread Block的线程数建议设置为32的整数倍。若线程数未满足该要求，最后一个Warp将包含不足32个线程，导致该Warp内存在空闲线程通道，从而降低执行效率。</p><h2 id="ub划分" tabindex="-1">UB划分 <a class="header-anchor" href="#ub划分" aria-label="Permalink to &quot;UB划分&quot;">​</a></h2><p>UB（即Unified Buffer）是同一线程块内所有线程均可访问的内存空间，位于每个AIV内部。UB内存空间总大小为256KB，参考<a href="#fig9500834165913">图2</a>，按功能划分为四个主要区域，从低地址向高地址依次为静态内存、动态内存、 预留空间 、Data Cache。</p><p><strong>图 2</strong> UB内存分配图<br><img src="`+d+`" alt="" title="UB内存分配图"></p><h2 id="内存空间说明" tabindex="-1">内存空间说明 <a class="header-anchor" href="#内存空间说明" aria-label="Permalink to &quot;内存空间说明&quot;">​</a></h2><ol><li><p>静态内存：从内存的起始地址分配一段指定大小的内存空间，其大小在编译时确定，不可动态修改。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 静态内存通过数组分配</span></span>
<span class="line"><span>__ubuf__ char static_buf[1024];</span></span></code></pre></div></li><li><p>动态内存：位于静态内存之后，通过<a href="./扩展语法/核函数配置.html#section2107535132111">&lt;&lt;&lt;...&gt;&gt;&gt;</a>中参数dyn_ub_size指定的动态内存大小空间，可通过以下方式申请使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 通过动态数组申请使用动态内存</span></span>
<span class="line"><span>extern __ubuf__ char dynamic_buf[];</span></span></code></pre></div></li><li><p>预留空间：系统预留空间，大小固定为8KB。</p></li><li><p>Data Cache：SIMT专有的Data Cache空间，UB内扣除静态内存、动态内存以及预留空间以后，剩余内存大小为Data Cache，Data Cache最小为32KB，剩余空间超过128KB时Data Cache大小固定为128KB，具体计算公式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DataCache =  UB总大小（256KB） –  静态内存 – 动态内存 – 预留空间(8KB）</span></span></code></pre></div><p>若DataCache小于32KB，会出现校验报错。</p></li></ol>`,32)])])}const k=t(p,[["render",r]]);export{g as __pageData,k as default};
